INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT136-S2-Q8$batch02$, 136, 2, 8, $batch02$Flaw$batch02$, $batch02$Robinson: Wexell says that the museum wasted its money in purchasing props and costumes from famous stage productions, because such items have no artistic significance outside the context of a performance. But many of the props and costumes are too old and fragile for use in a performance. So clearly, the museum did not waste its money, for displaying these items is the only way of making them available to the public.$batch02$, $batch02$The reasoning in Robinson's argument is most vulnerable to criticism on the grounds that it$batch02$, $batch02$B$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=136 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q8$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$offers anecdotal evidence insufficient to support a general claim$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$gives reasons that do not address the point made in Wexell's argument$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$attacks the person making the argument rather than the substance of the argument$batch02$, $batch02$Not Ad Hominem$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$concludes that a claim is false merely on the grounds that the evidence for it is insufficient$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$takes a condition that is sufficient for the conclusion to be true as one that is necessary for the conclusion to be true$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Wexell's claim$batch02$, $batch02$The money was wasted because the props and costumes have no artistic significance outside a performance.$batch02$), (1, $batch02$Robinson's conclusion$batch02$, $batch02$The money was not wasted.$batch02$), (2, $batch02$Robinson's evidence$batch02$, $batch02$The items are too fragile to perform with, so display is the only way the public can see them.$batch02$), (3, $batch02$Evaluate$batch02$, $batch02$Wexell's point is that the items mean nothing artistically once they are off the stage. Robinson replies that display is the only way to show them. Grant that. Does it show the items have artistic significance on display? No. If Wexell is right, displaying them is the only way to show the public something without artistic value. Robinson answered a question Wexell never asked.$batch02$), (4, $batch02$Goal$batch02$, $batch02$Look for the answer saying Robinson's reasons miss Wexell's point.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Robinson's evidence is about these particular props and costumes. He is not generalizing from anecdotes.$batch02$), ($batch02$B$batch02$, $batch02$Wexell's argument turns on artistic significance outside a performance. Robinson talks only about availability. Even if display is the only way to show the items, that does not answer whether they are worth showing.$batch02$), ($batch02$C$batch02$, $batch02$Robinson does not mention anything about Wexell personally.$batch02$), ($batch02$D$batch02$, $batch02$Robinson never claims Wexell's evidence is insufficient. He offers new reasons of his own, which happen to miss the point.$batch02$), ($batch02$E$batch02$, $batch02$"The only way" might suggest necessary vs sufficient, but there is no reversed conditional here. The trouble is relevance, not a scrambled condition.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT136-S2-Q8$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
